def min_tiles_to_draw(tiles):
    from collections import Counter

    # Count occurrences of each tile
    count = Counter(tiles)

    # Check for existing koutsu or shuntsu
    def has_koutsu(count):
        return any(v >= 3 for v in count.values())

    def has_shuntsu(count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            if suit in count:
                numbers = suits[suit]
                for i in range(len(numbers) - 2):
                    if numbers[i:i+3] in count[suit]:
                        return True
        return False

    if has_koutsu(count) or has_shuntsu(count):
        return 0

    # If no koutsu or shuntsu, determine the minimum tiles needed
    min_needed = float('inf')
    for tile in tiles:
        num, suit = tile[0], tile[1]
        for other_tile in tiles:
            if other_tile != tile and other_tile[0] == num and other_tile[1] == suit:
                remaining_tiles = [t for t in tiles if t != tile and t != other_tile]
                if has_koutsu(Counter(remaining_tiles)) or has_shuntsu(Counter(remaining_tiles)):
                    min_needed = min(min_needed, 2)
                break
        else:
            min_needed = min(min_needed, 1)

    return min_needed

