from collections import Counter

def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    tile_count = Counter(tiles)

    # Check for shuntsu
    def check_shuntsu():
        for i in range(1, 8):
            if tile_count[f'{i}m'] > 0 and tile_count[f'{i+1}m'] > 0 and tile_count[f'{i+2}m'] > 0:
                return True
            if tile_count[f'{i}p'] > 0 and tile_count[f'{i+1}p'] > 0 and tile_count[f'{i+2}p'] > 0:
                return True
            if tile_count[f'{i}s'] > 0 and tile_count[f'{i+1}s'] > 0 and tile_count[f'{i+2}s'] > 0:
                return True
        return False

    # Check for koutsu
    def check_koutsu():
        for tile in set(tiles):
            if tile_count[tile] >= 3:
                return True
        return False

    # If there is already a shuntsu or koutsu, no extra tiles are needed
    if check_shuntsu() or check_koutsu():
        return 0

    # Otherwise, we need at least one more tile to form a shuntsu or koutsu
    return 1

