import sys

def check_koutsu(tiles):
    count = {}
    for tile in tiles:
        if tile[0] in count:
            count[tile[0]] += 1
        else:
            count[tile[0]] = 1
    return any(value >= 3 for value in count.values())

def check_shuntsu(tiles):
    suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
    for suit in suits:
        indices = [i for i, tile in enumerate(tiles) if tile[1] == suit]
        for i in range(len(indices) - 2):
            if int(tiles[indices[i]][0]) + 1 == int(tiles[indices[i+1]][0]) and \
               int(tiles[indices[i+1]][0]) + 1 == int(tiles[indices[i+2]][0]):
                return True
    return False

def min_extra_tiles():
    tiles = [line.strip() for line in sys.stdin.readlines()]
    if check_koutsu(tiles) or check_shuntsu(tiles):
        return 0
    elif check_koutsu([tiles[0], tiles[1]]) or check_koutsu([tiles[0], tiles[2]]) or check_koutsu([tiles[1], tiles[2]]):
        return 1
    else:
        return 2

print(min_extra_tiles())
