from collections import Counter

def min_tiles_to_draw(tiles):
    # Count the occurrences of each tile
    tile_count = Counter(tiles)

    # Function to check if a set of three tiles forms a mentsu
    def is_mentsu(tiles):
        return len(set(tiles)) == 1 or (len(set(tiles)) == 3 and abs(int(tiles[0][0]) - int(tiles[1][0])) == 1 and abs(int(tiles[1][0]) - int(tiles[2][0])) == 1)

    # Check if there is already a mentsu in the hand
    for i in range(3):
        for j in range(i+1, 3):
            for k in range(j+1, 3):
                if is_mentsu([tiles[i], tiles[j], tiles[k]]):
                    return 0

    # Try drawing one more tile
    for i in range(1, 10):
        for suit in 'mps':
            new_tile = f"{i}{suit}"
            if tile_count[new_tile] > 0:
                tile_count[new_tile] -= 1
                for j in range(1, 10):
                    for k in range(j+1, 10):
                        for suit2 in 'mps':
                            new_tile2 = f"{j}{suit2}"
                            new_tile3 = f"{k}{suit2}"
                            if tile_count[new_tile2] > 0 and tile_count[new_tile3] > 0:
                                tile_count[new_tile2] -= 1
                                tile_count[new_tile3] -= 1
                                if is_mentsu([new_tile, new_tile2, new_tile3]):
                                    return 1
                                tile_count[new_tile2] += 1
                                tile_count[new_tile3] += 1
                tile_count[new_tile] += 1

    # If no mentsu can be formed with one more tile, try drawing two more tiles
    for i in range(1, 10):
        for suit in 'mps':
            new_tile = f"{i}{suit}"
            if tile_count[new_tile] > 0:
                tile_count[new_tile] -= 1
                for j in range(1, 10):
                    for k in range(j+1, 10):
                        for suit2 in 'mps':
                            new_tile2 = f"{j}{suit2}"
                            if tile_count[new_tile2] > 0:
                                tile_count[new_tile2] -= 1
                                for l in range(1, 10):
                                    for m in range(l+1, 10):
                                        for suit3 in 'mps':
                                            new_tile3 = f"{l}{suit3}"
                                            new_tile4 = f"{m}{suit3}"
                                            if tile_count[new_tile3] > 0 and tile_count[new_tile4] > 0:
                                                tile_count[new_tile3] -= 1
                                                tile_count[new_tile4] -= 1
                                                if is_mentsu([new_tile, new_tile2, new_tile3, new_tile4]):
                                                    return 2
                                                tile_count[new_tile3] += 1
                                                tile_count[new_tile4] += 1
                                tile_count[new_tile2] += 1
                tile_count[new_tile] += 1

    return 3

