    for i in range(1, 10):
        for suit in 'mps':
            new_tile = f'{i}{suit}'
            if tile_count[new_tile] > 0:
                tile_count[new_tile] -= 1
                if has_mentsu():
                    return 1
                tile_count[new_tile] += 1

    # If no mentsu can be formed with one tile, try with two tiles
    for i in range(1, 10):
        for j in range(i, 10):
            for suit1 in 'mps':
                for suit2 in 'mps':
