def min_tiles_to_draw(tiles):
    from collections import Counter

    # Count the occurrences of each tile
    count = Counter(tiles)

    # Check for koutsu
    koutsu_needed = 0
    for tile, freq in count.items():
        if freq < 3:
            koutsu_needed += 3 - freq

    # Check for shuntsu
    def can_form_shuntsu(suit):
        tiles_in_suit = sorted([tile[0] for tile in tiles if tile[1] == suit])
        for i in range(len(tiles_in_suit) - 2):
            if int(tiles_in_suit[i+1]) - int(tiles_in_suit[i]) == 1 and int(tiles_in_suit[i+2]) - int(tiles_in_suit[i+1]) == 1:
                return True
        return False

    shuntsu_needed = 0
    for suit in 'mps':
        if not can_form_shuntsu(suit):
            shuntsu_needed += 3

    # Return the maximum of koutsu and shuntsu needed
    return max(koutsu_needed, shuntsu_needed)

