def min_tiles_to_draw(tiles):
    from collections import Counter

    # Count the occurrences of each tile
    tile_count = Counter(tiles)

    # Function to check if a koutsu can be formed
    def can_form_koutsu(tile_count):
        return any(count >= 3 for count in tile_count.values())

    # Function to check if a shuntsu can be formed
    def can_form_shuntsu(tile_count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles = ''.join([tile[0] for tile in tiles if tile[1] == suit])
            for i in range(len(tiles) - 2):
                if tiles[i:i+3] in suits[suit]:
                    return True
        return False

    # Check if a mentsu can be formed without drawing any tiles
    if can_form_koutsu(tile_count) or can_form_shuntsu(tile_count):
        return 0

    # Try to form a mentsu by drawing one tile at a time
    for _ in range(2):
        for tile in ['1m', '2m', '3m', '4m', '5m', '6m', '7m', '8m', '9m',
                     '1p', '2p', '3p', '4p', '5p', '6p', '7p', '8p', '9p',
                     '1s', '2s', '3s', '4s', '5s', '6s', '7s', '8s', '9s']:
            tile_count[tile] += 1
            if can_form_koutsu(tile_count) or can_form_shuntsu(tile_count):
                return 1
            tile_count[tile] -= 1

    return 2

# Example usage
