from collections import defaultdict, deque

def min_tiles_to_win(tiles):
    def is_koutsu(hand):
        count = defaultdict(int)
        for tile in hand:
            count[tile[0]] += 1
        return any(count[suit] >= 3 for suit in 'mps')

    def is_shuntsu(hand):
        suits = {'m': [], 'p': [], 's': []}
        for tile in hand:
            suits[tile[1]].append(int(tile[0]))
        for suit in 'mps':
            nums = suits[suit]
            nums.sort()
            for i in range(len(nums) - 2):
                if nums[i+2] - nums[i] == 2:
                    return True
        return False

    def bfs():
        queue = deque([tiles])
        visited = set([tuple(sorted(tiles))])
        steps = 0

        while queue:
            for _ in range(len(queue)):
                current_hand = list(queue.popleft())
                if is_koutsu(current_hand) or is_shuntsu(current_hand):
                    return steps
                for suit in 'mps':
                    for num in range(1, 10):
                        new_tile = f"{num}{suit}"
                        if new_tile not in current_hand:
                            new_hand = sorted(current_hand + [new_tile])
                            if tuple(new_hand) not in visited:
                                visited.add(tuple(new_hand))
                                queue.append(new_hand)
            steps += 1

    return bfs()

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    result = min_tiles_to_win(data)
    print(result)
```

