import sys
from collections import Counter

def is_koutsu(tiles):
    count = Counter(tiles)
    return any(v >= 3 for v in count.values())

def is_shuntsu(tiles):
    suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
    for suit in suits:
        indices = [i for i, t in enumerate(tiles) if t[1] == suit]
        for i in range(len(indices) - 2):
            if int(suits[suit][indices[i]]) + 1 == int(suits[suit][indices[i+1]]) and \
               int(suits[suit][indices[i+1]]) + 1 == int(suits[suit][indices[i+2]]):
                return True
    return False

def min_extra_tiles():
    tiles = [line.strip() for line in sys.stdin.readlines()]
    if is_koutsu(tiles) or is_shuntsu(tiles):
        return 0
    else:
        return 1

if __name__ == "__main__":
    print(min_extra_tiles())
