import sys
from collections import Counter

def is_koutsu(tiles):
    count = Counter(tiles)
    return any(v >= 3 for v in count.values())

def is_shuntsu(tiles):
    tiles.sort()
    for i in range(len(tiles) - 2):
        if tiles[i][0] == tiles[i+1][0] == tiles[i+2][0]:
            if int(tiles[i][1]) + 1 == int(tiles[i+1][1]) == int(tiles[i+2][1]) - 1:
                return True
    return False

def min_extra_tiles(hand):
    tiles = sorted([tile[0] + tile[1] for tile in hand])
    if is_koutsu(tiles) or is_shuntsu(tiles):
        return 0
    elif is_koutsu(tiles[:3]) or is_shuntsu(tiles[:3]):
        return 1
    else:
        return 2

if __name__ == "__main__":
    hand = sys.stdin.read().strip().split()
    print(min_extra_tiles(hand))
